import { drizzle } from "drizzle-orm/d1";
import { schema } from "../../../database/schema";
import type { Database } from "../../Database";

/** Captures the SQL and parameters generated by one Drizzle statement. */
export interface RecordedQuery {
  readonly sql: string;
  readonly parameters: readonly unknown[];
}
/** Supplies raw SQLite rows for a generated SQL statement. */
export type RawRows = (sql: string) => readonly unknown[][];
/** Exposes a Drizzle database backed by an in-memory D1 statement recorder. */
export interface RecordedDatabase {
  readonly database: Database;
  readonly queries: readonly RecordedQuery[];
}

/** Creates a D1-compatible test adapter for asserting generated Drizzle queries. */
export const createRecordedDatabase = (rowsFor: RawRows): RecordedDatabase => {
  const queries: RecordedQuery[] = [];
  const client = {
    prepare: (sql: string) => {
      const statement = {
        bind: (...parameters: unknown[]) => {
          queries.push({ sql, parameters });
          return statement;
        },
        all: async () => ({ results: [] }),
        raw: async () => rowsFor(sql),
        run: async () => ({ success: true, meta: {}, results: [] }),
      };
      return statement;
    },
  };
  return {
    database: drizzle(client as unknown as D1Database, { schema }),
    queries,
  };
};
